.loader {
  background: linear-gradient(to right, #2cc16f 50%, #fafafa 50%);
  border-radius: 100%;
  height: 70px;
  width: 70px;
  animation: loader-circle-time 8s steps(800, start) infinite;
}

.loader:after {
  content: "";
  border-radius: 100% 0 0 100% / 50% 0 0 50%;
  height: 100%;
  left: 0;
  position: absolute;
  top: 0;
  width: 50%;
  animation: loader-circle-mask 8s steps(250, start) infinite;
  transform-origin: 100% 50%;
}

@keyframes loader-circle-time {
  100% {
    transform: rotate(360deg);
  }
}

@keyframes loader-circle-mask {
  0% {
    background: #fafafa;
    transform: rotate(0deg);
  }

  50% {
    background: #fafafa;
    transform: rotate(-180deg);
  }

  50.01% {
    background: #2cc16f;
    transform: rotate(0deg);
  }

  100% {
    background: #2cc16f;
    transform: rotate(-180deg);
  }
}

/* HTML: <div class="loader"></div> */
.loader {
  width: 35px;
  height: 80px;
  position: relative;
}

.loader:after {
  content: "";
  position: absolute;
  inset: 0;
  padding: 3px 5px;
  border-top: 1px solid #bbb6aa;
  border-bottom: 4px solid #bbb6aa;
  background: linear-gradient(#612329 0 0) bottom no-repeat content-box, 
    #e4e0d7;
  mix-blend-mode: darken;
  animation: l1 1.5s infinite linear;
}

.loader:before {
  content: "";
  position: absolute;
  inset: -18px calc(50% - 2px) 8px;
  background: #eb6b3e;
  transform-origin: bottom;
  transform: rotate(8deg);
}

@keyframes l1 {
  0% {
    background-size: 100% 100%
  }

  100% {
    background-size: 100% 5%
  }
}

.frame {
  position: relative;
  width: 800px;
  height: 600px;
  overflow: hidden;

  --time: 22s;
}

.frame *,
.frame *::before,
.frame *::after {
  content: "";
  position: absolute;
}

